//! System clipboard (text only) with change detection.

#[cfg(target_os = "macos")]
mod imp {
    use objc2::rc::autoreleasepool;
    use objc2_app_kit::{NSPasteboard, NSPasteboardTypeString};
    use objc2_foundation::NSString;

    /// Types password managers set so clipboard tools skip the item (nspasteboard.org).
    const SKIP_TYPES: [&str; 3] = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ];

    pub fn change_count() -> isize {
        autoreleasepool(|_| NSPasteboard::generalPasteboard().changeCount())
    }

    /// Current text, or None if empty, non-text, or marked secret/transient.
    pub fn read_text() -> Option<String> {
        autoreleasepool(|_| {
            let pb = NSPasteboard::generalPasteboard();
            let types = pb.types()?;
            let secret = (0..types.count()).any(|i| SKIP_TYPES.contains(&types.objectAtIndex(i).to_string().as_str()));
            if secret {
                return None;
            }
            let s = pb.stringForType(unsafe { NSPasteboardTypeString })?;
            Some(s.to_string())
        })
    }

    /// Writes text and returns the resulting change count (so the watcher can skip our own write).
    pub fn write_text(text: &str) -> isize {
        autoreleasepool(|_| {
            let pb = NSPasteboard::generalPasteboard();
            pb.clearContents();
            pb.setString_forType(&NSString::from_str(text), unsafe { NSPasteboardTypeString });
            pb.changeCount()
        })
    }
}

#[cfg(not(target_os = "macos"))]
mod imp {
    // shortcut: Windows clipboard not wired (use AddClipboardFormatListener / arboard) — sync is receive-less here
    pub fn change_count() -> isize {
        0
    }
    pub fn read_text() -> Option<String> {
        None
    }
    pub fn write_text(_text: &str) -> isize {
        0
    }
}

pub use imp::{change_count, read_text, write_text};
